import React from 'react';
import { createRoot } from 'react-dom/client';
import App from './App';

createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { useState } from 'react';
import { countCharacters, countWords } from '../stats.mjs';

export default function App() {
  const [text, setText] = useState('');
  const [charCount, setCharCount] = useState(0);
  const [wordCount, setWordCount] = useState(0);
  const [showResult, setShowResult] = useState(false);

  const handleStat = () => {
    setCharCount(countCharacters(text));
    setWordCount(countWords(text));
    setShowResult(true);
  };

  const handleClear = () => {
    setText('');
    setCharCount(0);
    setWordCount(0);
    setShowResult(false);
  };

  const handleExample = () => {
    setText('你好 😀世界\t!');
    setShowResult(false);
  };

  return (
    <div className="container">
      <h1>文本统计器 · React</h1>
      <label htmlFor="inputText">输入文本</label>
      <textarea
        id="inputText"
        value={text}
        onChange={(e) => setText(e.target.value)}
        placeholder="在此输入或粘贴文本..."
        rows={8}
      />
      <div className="btn-row">
        <button onClick={handleStat}>统 计</button>
        <button onClick={handleClear}>清 空</button>
      </div>
      <button className="example-btn" onClick={handleExample}>示例文本</button>
      {showResult && (
        <div className="result">
          <p>字符数：<span className="num">{charCount}</span></p>
          <p>单词数：<span className="num">{wordCount}</span></p>
        </div>
      )}
    </div>
  );
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { countCharacters, countWords } from '../stats.mjs';

test('中文字符数', () => {
	assert.equal(countCharacters('你好世界'), 4);
});

test('中文词数', () => {
	assert.equal(countWords('你好 世界'), 2);
});

test('非BMP emoji 字符数', () => {
	assert.equal(countCharacters('\uD83D\uDE00'), 1);
});

test('非BMP emoji 词数', () => {
	assert.equal(countWords('😀🎉'), 1);
});

test('混合字符数', () => {
	assert.equal(countCharacters('a😀b'), 3);
});

test('Tab 和换行分隔词数', () => {
	assert.equal(countWords('hello\tworld\nfoo'), 3);
});

test('Tab 和换行计字符', () => {
	assert.equal(countCharacters('a\t\nb'), 4);
});

test('纯空白词数', () => {
	assert.equal(countWords('   \n\t  '), 0);
});

test('空字符串词数', () => {
	assert.equal(countWords(''), 0);
});

test('普通多词词数', () => {
	assert.equal(countWords('Hello world foo bar'), 4);
});

test('普通多词字符数', () => {
	assert.equal(countCharacters('Hello world'), 11);
});

test('单字词数', () => {
	assert.equal(countWords('one'), 1);
});

test('混合中文 emoji 空白 字符数', () => {
	assert.equal(countCharacters('你好 😀\n世界\t!'), 9);
});

test('混合中文 emoji 空白 词数', () => {
	assert.equal(countWords('你好 😀\n世界\t!'), 4);
});

test('示例文本：你好 😀世界\t!', () => {
	const t = '你好 😀世界\t!';
	assert.equal(countCharacters(t), 8);
	assert.equal(countWords(t), 3);
});

